#include <iostream>
#include <map>
#include <sstream>
#include <string>

std::map<std::string, int> WordFrequency(const std::string& text);

int main()
{
    std::string line;
    while (std::getline(std::cin, line))
    {
        std::map<std::string, int> counts = WordFrequency(line);
        bool first = true;
        for (const auto& entry : counts)
        {
            if (!first) { std::cout << " "; }
            std::cout << entry.first << ":" << entry.second;
            first = false;
        }
        std::cout << "\n";
    }
    return 0;
}

